# content_hcc.py — 간암 원고의 Methods·Results 문장(수치는 numbers_hcc에서만). 서론·고찰·결론·초록은 draft md.
#  인용 = [@key](manifest key) 또는 [@web:...]. 단독 저자 → 1인칭 금지. 미국식 철자. 결과 절에 해석 금지. 제목은 시리즈 틀 반복 금지(11/5 저자 규칙).
from numbers_hcc import load, ROB, RS
import os, pandas as pd
N = load()
def ci(v, src=None):
    r = (src or N["main"])[v]
    return f"RR {r['IRR']:.3f}; 95% CrI {r['lo']:.3f}-{r['hi']:.3f}"
from decimal import Decimal, ROUND_HALF_UP
_r2 = lambda x: str(Decimal(str(round(float(x), 3))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
def tci(t): return f"RR {t[0]:.3f}; 95% CrI {t[1]:.3f}-{t[2]:.3f}"
M = N["main"]; T1 = N["T1"]
S43 = lambda a, v: N["s43"][(a, v)]
dW = lambda a: N["s43_waic"][a] - N["waic_main"]
NCO = lambda o, v: N["nco"][(o, v)]
NC = lambda v: (N["negctl"][v]["IRR"], N["negctl"][v]["lo"], N["negctl"][v]["hi"])
SC = lambda s, v: N["sens_main"][s][v]
EN = {"전라남도": "South Jeolla", "경상북도": "North Gyeongsang", "경상남도": "South Gyeongsang", "충청남도": "South Chungcheong", "전라북도": "North Jeolla",
      "강원도": "Gangwon", "부산시": "Busan", "충청북도": "North Chungcheong", "대구시": "Daegu", "경기도": "Gyeonggi", "서울시": "Seoul", "인천시": "Incheon",
      "광주시": "Gwangju", "울산시": "Ulsan", "대전시": "Daejeon", "세종시": "Sejong", "제주도": "Jeju"}
def sidos(d, n):
    return ", ".join(f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n])
def sidos3(d, n):
    l = [f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n]]; return ", ".join(l[:-1]) + ", and " + l[-1]
KH = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
def kh_list(v):
    return [t[3:].replace("type", "") for t in KH if S43(t, v)[3] and (S43(t, v)[0] > 1) == (M[v]["IRR"] > 1)]
def roman(l): return "none" if not l else (l[0] if len(l) == 1 else (" and ".join(l) if len(l) == 2 else ", ".join(l[:-1]) + ", and " + l[-1]))
TITLE = "Does liver cancer care remain concentrated in southern Korean districts after age adjustment?"
RUNNING = "Liver cancer care in Korean districts"   # running title < 40자(공백 포함)
KEYWORDS = "Liver Neoplasms; Republic of Korea; Small-Area Analysis; Socioeconomic Factors; Spatio-Temporal Analysis"   # 3-5개, MeSH
_R14 = N["ret14"]; assert len(KEYWORDS.split(";")) <= 5

METHODS = [
("Data sources and outcome",
 f"This ecological study used annual numbers of people treated for liver cancer (International Classification of Diseases, 10th revision, C22 as the principal diagnosis) in 2011-2024 from the Regional Medical Care Utilization Statistics of the National Health Insurance Service [@web:nhis2026regional], which cover National Health Insurance and Medical Aid beneficiaries and attribute each person to the district of residence. Each count is the number of unique people with at least one such claim in a year; it reflects people under care for liver cancer, combining incidence, survival, and treatment, rather than incidence, and the category C22 includes intrahepatic cholangiocarcinoma as well as hepatocellular carcinoma. Districts were harmonized to {N['n_districts']} units with 2024 boundaries ({N['n_rows']:,} district-years), with mid-year resident registration populations by 5-year age group as denominators [@web:mois2026population] (the Supporting Information)."),
("Age standardization",
 "Expected counts were obtained by indirect standardization: national age-specific treatment rates in ten age groups (to 75 years or older, the finest grouping available in every year) were applied to each district's age structure and rescaled each year to the national total [@inskip1983methods]. The ratio of observed to expected counts is the standardized treatment ratio (STR), which describes each district's position relative to the national age-specific rates of the same year; national change over time was assessed separately by direct standardization to the 2015 population. National tables are not published by sex, so standardization was by age only."),
("Covariates",
 f"Before the age-standardized models were fitted, {N['n_hyp']} district characteristics were specified from the literature with an expected direction (documented on 5 November 2026 and archived with the code; not a registered protocol): behaviors (high-risk drinking and current smoking from the Community Health Survey [@kang2015korea]); metabolic and liver risk at national health screening (the shares of screened adults classified as needing lifestyle management for obesity, fasting glucose, or liver function, that is, borderline findings below the thresholds for suspected disease); physical activity and its environment (walking, moderate-or-vigorous activity, and densities per 100,000 population of public sports facilities, public community gyms, and village sports facilities); social structure and deprivation (Medical Aid type 1 beneficiaries receiving care per 100,000, a care-based deprivation proxy; older-adult single-person households; old housing; and regular employment); and general health screening uptake as a marker of detection. District indicators of hepatitis B or C infection were not available, and care-based liver disease measures were excluded because they overlap the outcome. Five controls were forced into every model: urban population share, physician density, sex ratio, fiscal autonomy (the share of a district's budget it can spend at its own discretion), and the share aged 80 years or older, because the oldest standardization group cannot capture differences in very old age. Covariates were standardized to 1 standard deviation (SD) across all district-years, and missing years were filled within districts (Table S1)."),
("Statistical analysis",
 "Counts were modeled with a Poisson likelihood, chosen over a negative binomial likelihood by the lower widely applicable information criterion (WAIC) of the forced-controls model, an offset of log expected counts, a Besag-York-Mollié 2 (BYM2) district effect with penalized-complexity priors [@riebler2016intuitive], and random-walk and independent year effects, using integrated nested Laplace approximation [@rue2009approximate]. This model was prespecified as principal; space-time interaction models were sensitivity analyses because interaction terms absorb district-specific trends together with part of the covariate variation. Rate ratios (RRs) per 1 SD are reported with 95% credible intervals (CrIs), and an association was described as credible when the interval excluded 1; intervals were not adjusted for multiplicity, so findings across the 15 covariates are exploratory. In a covariate-subset analysis adapted from multiverse analysis [@steegen2016increasing], 200 random subsets of the hypothesis covariates were fitted with all forced controls, and a covariate was subset-stable if its CrI excluded 1 in at least 75% of the subsets containing it with the same sign in at least 95%. Residual hot and cold spots, which describe district effects after covariate adjustment, were districts with a marginal posterior probability of a residual RR above 1 of more than 0.95 or less than 0.05, for the full period and three windows (2011-2015, 2016-2019, 2020-2024). Gradients were assessed by Spearman correlation across the 229 districts of full-period empirical Bayes-smoothed STRs with district northing, Medical Aid care, and fiscal autonomy, and persistence by Kendall's W of annual STR rankings and emerging hot spot analysis. Models were fitted in R with R-INLA [@web:rcore2026]."),
("Sensitivity analyses and reporting",
 "Knorr-Held type I-IV space-time interactions were added with sum-to-zero constraints for each connected component of the adjacency graph [@knorrheld2000bayesian]. Subset-stable covariates were decomposed into district means and two-way-centered within-district deviations [@bell2015explaining], and the principal model was refitted in each calendar window. Further analyses varied the likelihood, time effects, priors, neighborhoods, adjacency graph, and expected-count age groups, added a Spatial+-type adjustment [@dupont2022spatial] and a COVID-19 period interaction, lagged covariates, omitted each province, each year, or the share aged 80 years or older, and perturbed filled values (Tables S2-S5). Treated gastric cancer and arthritis served as comparison outcomes that share care-seeking and socioeconomic determinants but not liver-specific pathways (infectious diseases were not used because they include viral hepatitis), so an association of similar size was read as limited outcome specificity, without distinguishing shared determinants from care use; hit-and-run accidents, a traffic culture index, and fires served as negative-control exposures [@lipsitch2010negative]. E-values quantified the confounding needed to explain associations [@vanderweele2017sensitivity], and posterior predictive checks, including prediction of held-out 2024 counts, assessed fit. An institutional review board approved the study and waived informed consent because only published aggregate statistics were used, and the study was performed in accordance with the Declaration of Helsinki (2013 revision). Claude (Anthropic) and ChatGPT (OpenAI) were used only for translation and English-language editing of the manuscript. The study complies with the STROBE statement [@vonelm2007strengthening] and its RECORD extension for routinely collected health data [@benchimol2015reporting] (checklist provided separately)."),
]

_W = pd.read_csv(os.path.join(RS, "S4_window_IRR.csv"))
def _wc(v, w): r = _W[(_W["cov"] == v) & (_W.window == w)].iloc[0]; return bool(r.cred) and (r.IRR > 1) == (M[v]["IRR"] > 1)
_WCRED = {v: [w for w in ("W1_2011-15", "W2_2016-19", "W3_2020-24") if _wc(v, w)] for v in ROB}
assert _WCRED == {"screening_normalB_obesity_share": [], "screening_normalB_diabetes_share": [], "screening_normalB_liver_share": [], "medical_aid1_patients_per_100k": ["W1_2011-15"], "regular_employee_share": []}, _WCRED
RESULTS = [
("Treated people and trends",
 f"Over 2011-2024, annual counts of treated people summed to {N['cases_total']/1e3:,.0f} thousand against {N['py']/1e6:.1f} million person-years (Table 1). The crude treatment rate rose from {N['crude_2011']:.1f} to {N['crude_2024']:.1f} per 100,000 ({100*(N['crude_2024']/N['crude_2011']-1):.0f}% increase), whereas the age-standardized rate fell from {N['asr_2011']:.1f} to {N['asr_2024']:.1f} ({100*(1-N['asr_ratio']):.0f}% decrease) (Figure 1). The 10th-90th percentile range of district STRs was {T1['2011-2024']['sir_p10']:.2f}-{T1['2011-2024']['sir_p90']:.2f}."),
("Spatial pattern and persistence",
 f"Moran's I of the log STR was {N['moran_pooled']:.2f} (annual range {_r2(N['moran_year_min'])}-{_r2(N['moran_year_max'])}), and the BYM2 spatial fraction was {N['phi'][0]:.2f} (95% CrI {N['phi'][1]:.2f}-{N['phi'][2]:.2f}). Residual RRs ranged from {N['rr_min']:.2f} to {N['rr_max']:.2f}. There were {N['n_hot']} residual hot spots, mainly in {sidos3(N['hot_by_sido'], 5)}, {N['type_class']['hotspot']['county']} of them rural counties, and {N['n_cold']} cold spots, {N['cold_capital']} of them in the capital region (Gyeonggi, Seoul, and Incheon) and {N['cold_by_sido']['충청남도']} in South Chungcheong (Figure 1). In all three windows, {N['hot_all_windows']} districts were hot spots and {N['cold_all_windows']} were cold spots (Figure S1). Kendall's W of annual rankings was {N['kendall_W']:.2f}. Smoothed STRs correlated with northing (ρ {N['lat_eb']:.2f}), Medical Aid care (ρ {N['eb_aid']:.2f}), and fiscal autonomy (ρ {N['eb_fis']:.2f})."),
("District correlates in the principal model",
 f"The {N['n_hyp']} covariates improved fit over the forced controls alone (ΔWAIC {N['waic_main']-N['waic_forced']:.0f}); {N['n_cred_hyp']} were credible and {N['n_robust']} subset-stable (Table 2). Per 1 SD, treatment was higher with more Medical Aid care ({ci('medical_aid1_patients_per_100k')}), a larger share needing diabetes management ({ci('screening_normalB_diabetes_share')}), and a larger share needing liver-function management ({ci('screening_normalB_liver_share')}), and lower with a larger share needing obesity management ({ci('screening_normalB_obesity_share')}) and more regular employment ({ci('regular_employee_share')}); these five were subset-stable. Walking ({ci('walking_practice_rate')}), old housing, and older-adult single-person households were credible but not subset-stable. High-risk drinking ({ci('high_risk_drinking_rate')}), current smoking, moderate or vigorous activity, the three sports facility densities, and screening uptake were not credibly associated in the principal model; current smoking was credible in some interaction models. Hit-and-run accidents, a negative-control exposure, were associated with more treatment ({tci(NC('hit_and_run_rate'))}); the other two were not. The COVID-19 period had no credible main effect ({tci(N['covid_main'])})."),
("Space-time interaction and other sensitivity analyses",
 f"All four interaction types fit better than the principal model (ΔWAIC {min(dW(a) for a in KH):,.0f} to {max(dW(a) for a in KH):,.0f}), type IV best. Medical Aid care remained credible in types {roman(kh_list('medical_aid1_patients_per_100k'))}, obesity management and regular employment in types {roman(kh_list('regular_employee_share'))}, and diabetes and liver-function management only in type I, so among the five subset-stable covariates only Medical Aid care remained credible in the best-fitting type IV model, in which current smoking was also credible (Figure 2). "
 f"Within-district components were credible for Medical Aid care ({tci(N['bw']['medical_aid1_patients_per_100k__within'])}), diabetes management, liver-function management, and obesity management ({tci(N['bw']['screening_normalB_obesity_share__within'])}), whose between-district component was in the opposite direction ({tci(N['bw']['screening_normalB_obesity_share__between'])}); the between-district component of Medical Aid care and both components of regular employment were not credible. In separate fits for each calendar window, Medical Aid care was credible only in 2011-2015 and screening uptake, inversely, only in 2011-2015 and 2016-2019; no covariate was credible in every window (Table S5). Medical Aid care and obesity management remained credible with the same sign in {_R14['medical_aid1_patients_per_100k'][0]} of {_R14['medical_aid1_patients_per_100k'][1]} alternative specifications, regular employment in {_R14['regular_employee_share'][0]}, liver-function management in {_R14['screening_normalB_liver_share'][0]}, and diabetes management in {_R14['screening_normalB_diabetes_share'][0]}, and all five remained credible after omission of the share aged 80 years or older (Tables S2 and S3). "
 f"Medical Aid care was also associated with treated gastric cancer ({tci(NCO('GCA','medical_aid1_patients_per_100k'))}) and arthritis ({tci(NCO('ARTH','medical_aid1_patients_per_100k'))}); obesity management was inversely associated with both, and diabetes management, liver-function management, and regular employment were associated with arthritis only, with estimates near 1. E-values were {min(v['E_point'] for v in N['evalue'].values()):.2f}-{max(v['E_point'] for v in N['evalue'].values()):.2f}. Residual Moran's I was {N['moran_resid']:.2f} (permutation <i>P</i> = {N['moran_resid_p']:.3f}), 95% posterior predictive intervals covered {100*N['ppc']['coverage95']:.1f}% of district-years, although probability integral transform values departed from uniformity, and 95% intervals covered {100*N['oos']['coverage95']:.0f}% of held-out 2024 counts conditional on national totals, below the nominal level (Table S4)."),
]

# 문장 주장 대조
assert not N['bw']['medical_aid1_patients_per_100k__between'][3] and kh_list('current_smoking_rate') and [w for w in ('W1_2011-15','W2_2016-19','W3_2020-24') if bool(_W[(_W['cov']=='screening_uptake')&(_W.window==w)].cred.iloc[0])]==['W1_2011-15','W2_2016-19'] and _W.groupby('cov').cred.sum().max()<3
assert kh_list("medical_aid1_patients_per_100k") == ["I", "III", "IV"] and kh_list("regular_employee_share") == kh_list("screening_normalB_obesity_share") == ["I", "III"]
assert kh_list("screening_normalB_diabetes_share") == kh_list("screening_normalB_liver_share") == ["I"]
assert min(N["s43_waic"][a] for a in KH) == N["s43_waic"]["KH_typeIV"] and all(dW(a) < 0 for a in KH)
assert all(N["bw"][v + "__within"][3] for v in ("medical_aid1_patients_per_100k", "screening_normalB_diabetes_share", "screening_normalB_liver_share", "screening_normalB_obesity_share"))
assert N["bw"]["screening_normalB_obesity_share__between"][3] and N["bw"]["screening_normalB_obesity_share__between"][0] > 1
assert not any(N["bw"][f"regular_employee_share__{k}"][3] for k in ("within", "between"))
assert NCO("GCA", "medical_aid1_patients_per_100k")[3] and NCO("ARTH", "medical_aid1_patients_per_100k")[3]
assert NCO("GCA", "screening_normalB_obesity_share")[3] and NCO("ARTH", "screening_normalB_obesity_share")[3] and NCO("GCA", "screening_normalB_obesity_share")[0] < 1 and NCO("ARTH", "screening_normalB_obesity_share")[0] < 1
assert all(NCO("ARTH", v)[3] and not NCO("GCA", v)[3] for v in ("screening_normalB_diabetes_share", "screening_normalB_liver_share", "regular_employee_share"))
assert all(SC("s2", v)[3] for v in ROB)
assert N["negctl"]["hit_and_run_rate"]["cred"] and not N["negctl"]["traffic_culture_index"]["cred"] and not N["negctl"]["fires_per_10000"]["cred"]
assert not any(M[v]["cred"] for v in ("high_risk_drinking_rate", "current_smoking_rate", "moderate_pa_rate", "public_sports_facilities_per_100k", "community_gyms_per_100k", "village_sports_facilities_per_100k", "screening_uptake"))
assert all(M[v]["cred"] and not N["mv"][v]["robust"] for v in ("walking_practice_rate", "old_housing_share", "older_single_household_share")) and not N["covid_main"][3]

if __name__ == "__main__":
    for h, t in METHODS + RESULTS: print("##", h, "\n", t, "\n")
